#!/usr/bin/env python3
"""Writes docs/hyperframes-compatibility-matrix.md (every catalog resource) from catalog.classification.json + catalog.enabled.json."""
import json, os, collections
R = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
c = json.load(open(f'{R}/src/lib/hyperframes/catalog.classification.json')); items = c['items']
en = {i['id']: i for i in json.load(open(f'{R}/src/lib/hyperframes/catalog.enabled.json'))['items']}
L = ['# HyperFrames compatibility matrix (every catalog resource)', '', f"Generated by `scripts/hyperframes/matrix.py` from `catalog.classification.json` and `catalog.enabled.json`. Pinned upstream `{c['upstreamCommit']}`. SSIM = production-path render vs a native HyperFrames snapshot at 3 sample times (worst sample).", '']
L += ['## Totals', '', '| Type | verified | adapter-compatible | specialized | host-dependent | unsupported | not-tested | enabled |', '|---|---|---|---|---|---|---|---|']
for t, n in (('block', 'Blocks (210)'), ('component', 'Components (238)'), ('example', 'Starter projects (9)')):
    cs = collections.Counter(v['status'] for v in items.values() if v['type'] == t)
    L.append(f"| {n} | {cs['verified-export']} | {cs['adapter-compatible']} | {cs['specialized']} | {cs['host-dependent']} | {cs['unsupported']} | {cs['not-tested']} | {sum(1 for i in en.values() if i.get('type', 'block') == t)} |")
for t, title in (('block', 'Blocks'), ('component', 'Components'), ('example', 'Starter projects')):
    L += ['', f'## {title}', '', '| Resource | Status | Enabled | SSIM min | Kind | Export fps | Editable fields | Reason / blocker |', '|---|---|---|---|---|---|---|---|']
    for k, v in sorted(items.items()):
        if v['type'] != t: continue
        ev = v.get('evidence') or {}; ex = ev.get('export') or {}
        ssim = ev.get('prodSsimMin', ''); fps = ex.get('fps', '')
        why = ('; '.join(v['enabledBlockedBy']) if v['status'] == 'verified-export' and not v['enabled'] and v['enabledBlockedBy'] else v['reason'])[:150].replace('|', '/')
        L.append(f"| {k} | {v['status']} | {'yes' if v['enabled'] else 'no'} | {ssim} | {ev.get('kind', '')} | {fps} | {len(en[k]['editables']) if k in en else ''} | {why} |")
open(f'{R}/docs/hyperframes-compatibility-matrix.md', 'w').write('\n'.join(L) + '\n'); print(len(L), 'lines')
